<script lang="ts">let{data}=$props();</script><div class="page"><header class="page-head"><div><h1>Access requests</h1><p>Permission to see protected state is separate from the physical reality and may be revoked independently.</p></div></header>{#if data.error}<p class="error">{data.error}</p>{/if}<div class="list">{#each data.rows as row}<article class="surface"><div class="row-between"><div><p class="eyebrow">Protected current state</p><h2>{row.target_entity_id}</h2><p class="muted">Permission: {row.requested_permission}</p></div><span class="status">{row.status}</span></div><dl class="summary-grid"><div><dt>Requested</dt><dd>{new Date(row.requested_at).toLocaleString()}</dd></div><div><dt>Decision</dt><dd>{row.decided_at?new Date(row.decided_at).toLocaleString():'Pending'}</dd></div></dl>{#if row.decision_reason}<p class="notice">{row.decision_reason}</p>{/if}</article>{:else}<div class="surface"><p class="muted">No access requests yet.</p></div>{/each}</div></div>